import json
with open('baseline-packages.json') as f: base = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for p in fw.get('topLevelPackages', []):
                key = (name, tfm, p['id'])
                result[key] = p['resolvedVersion']
    return result

b = get_pkgs(base)
a = get_pkgs(after)
changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'MISSING')
    av = a.get(k, 'MISSING')
    if bv != av:
        changes.append(f'{k[0]} ({k[1]}): {k[2]} {bv} -> {av}')
if changes:
    print('CHANGES:')
    for c in changes: print(f'  {c}')
else:
    print('No changes - all packages resolve identically')
"

